import{_ as u,C as o,o as d,c as m,j as t,a,E as s,a8 as g}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/-AOxpwVeIWw-640.webp",b="/schedule-dashboard/thumbs/yt/-AOxpwVeIWw-1280.webp",r="/schedule-dashboard/thumbs/yt/7T-gldvgfpo-640.webp",f="/schedule-dashboard/thumbs/yt/7T-gldvgfpo-1280.webp",i="/schedule-dashboard/thumbs/yt/W4pnzOURwHQ-640.webp",v="/schedule-dashboard/thumbs/yt/W4pnzOURwHQ-1280.webp",l="/schedule-dashboard/thumbs/yt/obfPzbapMIM-640.webp",y="/schedule-dashboard/thumbs/yt/obfPzbapMIM-1280.webp",h="/schedule-dashboard/thumbs/yt/q4WC4TowkBo-640.webp",k="/schedule-dashboard/thumbs/yt/q4WC4TowkBo-1280.webp",p="/schedule-dashboard/thumbs/yt/OfNajAPiGsM-640.webp",_="/schedule-dashboard/thumbs/yt/OfNajAPiGsM-1280.webp",j=JSON.parse('{"title":"AI Digest · Mon 19 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-19","routine":"digest"},"relativePath":"digest/2026-10-19.md","filePath":"digest/[date].md"}'),A={name:"digest/2026-10-19.md"},q=n+" 640w, "+b+" 1280w",I=r+" 640w, "+f+" 1280w",P=i+" 640w, "+v+" 1280w",T=l+" 640w, "+y+" 1280w",x=h+" 640w, "+k+" 1280w",M=p+" 640w, "+_+" 1280w",O={id:"ai-digest-·-mon-19-oct-2026",tabindex:"-1"};function W(C,e,R,B,z,S){const c=o("Badge"),w=o("DayFilter");return d(),m("div",null,[t("h1",O,[e[0]||(e[0]=a("AI Digest · Mon 19 Oct 2026 ",-1)),s(c,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-mon-19-oct-2026","aria-label":'Permalink to "AI Digest · Mon 19 Oct 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack, last 24h (19 Oct 2026) · run date Mon 19 Oct 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer"),a(` posted 5 videos (about 3.8 hours). The freshest is Jan Curn's 21-minute Apify talk on why agent payments (x402, MPP and the rest) still see almost no real volume, with API keys and subsidised tokens as the real rival. OpenProse's "declare the outcome, not the steps" markdown contracts and Denys Linkov's insurance-claims data talk (with a medical-records model benchmark) are the most new ground. WorkOS's verification-loop workshop has a useful hands-on verifier CLI, while Langfuse's high-stakes evals workshop is mostly a repeat of the Phoenix evals session and Langfuse's own earlier workshop.`)]),t("p",null,[t("strong",null,"Better Stack"),a(` posted 1 video: a 6-minute explainer on Anthropic's Frontier Red Team test of a self-replicating AI "worm" on cheap Android TV boxes. It's a new topic and worth the six minutes.`)])],-1)),s(w),e[5]||(e[5]=g('<div class="grid cards2"><article class="it full" id="v--AOxpwVeIWw" data-title="Why AI Agents Still Won&#39;t Pay for Anything — Jan Curn, Apify" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=-AOxpwVeIWw" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=-AOxpwVeIWw" target="_blank" rel="noopener">Why AI Agents Still Won&#39;t Pay for Anything — Jan Curn, Apify</a></h3><div class="meta">AI Engineer · Jan Curn, Apify · uploaded 19 Oct, 4:30 AM IST · 20:37</div><div class="verdict v-skim"><b>Verdict:</b> skim from 8:36 — the funnel analysis (API keys as the real rival, token subsidies, trusted directories) and Apify&#39;s batch-settlement story are new; the protocol list and x402 basics have been covered before, including in his earlier talk &quot;x402 isn&#39;t good (yet)&quot;.</div><div class="sh">Lots of protocols, almost no volume</div><ul><li><strong>Why Apify cares:</strong> Apify&#39;s store has about 80,000 &quot;actors&quot; (scraping/automation tools) built by outside creators, and it paid those creators almost $2M last month, so agent payments are just another sales channel for it (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=34s" target="_blank" rel="noopener">0:34</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=79s" target="_blank" rel="noopener">1:19</a>)</li><li><strong>Protocol pile-up:</strong> He lists L402 (Lightning Labs), Mastercard Agent Pay, x402 (Coinbase, May 2025, &quot;probably the most popular&quot;), Skyfire&#39;s KYAPay, Google&#39;s AP2, OpenAI + Stripe&#39;s ACP, Visa&#39;s TAP, Google + Shopify&#39;s UCP, Stripe + Tempo&#39;s MPP, plus Alipay, UnionPay and OKX protocols. He also cites a Gartner forecast of a $15T agent economy by 2028, with 80% of B2B activity run by agents (he calls that &quot;a little too much&quot;) (repeat) (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=164s" target="_blank" rel="noopener">2:44</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=301s" target="_blank" rel="noopener">5:01</a>)</li><li><strong>Why crypto fits:</strong> Cards and PayPal cost too much for tiny agent transactions. Chargebacks can&#39;t work when there are &quot;an infinite number of agents&quot; that could take a service for free. Crypto has no chargebacks, only optional refunds, and no single owner. That&#39;s why x402 and Stripe&#39;s MPP both settle in stablecoins (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=328s" target="_blank" rel="noopener">5:28</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=428s" target="_blank" rel="noopener">7:08</a>)</li><li><strong>Near-zero real usage:</strong> Over the last 30 days, x402scan/mppscan show only about $1M of volume on x402 and about $1.5K on MPP. Apify, Exa, Perplexity and Firecrawl together earn far more than $1M a month from agents, but through API keys, not autonomous discovery and payment (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=431s" target="_blank" rel="noopener">7:11</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=516s" target="_blank" rel="noopener">8:36</a>)</li></ul><div class="sh">The funnel: need → setup → discovery → buy</div><ul><li><strong>Need — the rival is API keys, not Visa:</strong> People sign up once, paste an API key or connect over MCP, and pay by card. Three things could change that: better models earning trust with money ($5, then $50, then $500 a job), always-on personal agents that need a budget, and the end of token subsidies. A $100/month Claude plan can burn about $14,000 of tokens, so agents have no reason to buy a service when building it costs them nothing (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=565s" target="_blank" rel="noopener">9:25</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=739s" target="_blank" rel="noopener">12:19</a>)</li><li><strong>Setup — wallets are still hard:</strong> Most people have never set up a crypto wallet for an agent. He sees the big unlock as Claude, ChatGPT and similar agents building payments in, e.g. &quot;you can use $50 of credits to buy services&quot; (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=743s" target="_blank" rel="noopener">12:23</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=808s" target="_blank" rel="noopener">13:28</a>)</li><li><strong>Discovery — who can an agent trust?</strong> People historically built trust through their own network and through trusted middlemen like marketplaces, reviews and consumer agencies. For agents, the equivalents are curated directories: Claude&#39;s carefully reviewed connector directory, ChatGPT apps and the Apify store (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=818s" target="_blank" rel="noopener">13:38</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=980s" target="_blank" rel="noopener">16:20</a>)</li></ul><div class="sh">Pay-per-use finally works</div><ul><li><strong>x402 flow and its risk:</strong> The request gets a 402 with a payment-required header. The client re-sends it signed, a facilitator (e.g. Coinbase) verifies and settles on-chain, and only then is the work done. If you do the work before settlement, you can lose money (repeat) (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=1041s" target="_blank" rel="noopener">17:21</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=1099s" target="_blank" rel="noopener">18:19</a>)</li><li><strong>From &quot;exact&quot; to batch settlement:</strong> x402&#39;s &quot;exact&quot; scheme only covers fixed prices. &quot;upto&quot; let a buyer spend the same money twice because settlement happened later. Apify worked around this with exact + refund (e.g. charge $10 up front, refund the unused part), which costs two on-chain fees and needs buyer trust. x402&#39;s new batch settlement (an on-chain escrow that is drawn down by micro-charges) fixes it, and Apify added it &quot;last week&quot;. MPP added sessions for the same purpose (<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=1110s" target="_blank" rel="noopener">18:30</a>–<a href="https://www.youtube.com/watch?v=-AOxpwVeIWw&amp;t=1196s" target="_blank" rel="noopener">19:56</a>)</li></ul></div></article><article class="it full" id="v-7T-gldvgfpo" data-title="Stop Telling Agents How — Dan Barrett, Raymond Weitekamp &amp; Jose Montes de Oca, OpenProse" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=7T-gldvgfpo" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=7T-gldvgfpo" target="_blank" rel="noopener">Stop Telling Agents How — Dan Barrett, Raymond Weitekamp &amp; Jose Montes de Oca, OpenProse</a></h3><div class="meta">AI Engineer · Dan Barrett, Raymond Weitekamp &amp; Jose Montes de Oca, OpenProse · uploaded 19 Oct, 12:30 AM IST · 49:36</div><div class="verdict v-skim"><b>Verdict:</b> skim from 9:58 — the contract-as-compiler idea, the DSPy comparison (26:39) and the bank-docs demo (31:35) are the substance; the live voice-agent demo and Q&amp;A wander.</div><div class="repeat">🔁 Repeat: &#39;harness engineering&#39; — seen 22 times before. New here: OpenProse is a &quot;meta-harness&quot; layer, plain markdown that any harness (Claude Code, Codex, your own) compiles and runs.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 18 times before. New here: PR reviews run as fresh sessions checked against a declared contract; some PRs took 14 review rounds.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 11 times before. New here: multi-agent shapes (fan-out/fan-in, adversarial review, loop-until) written as markdown &quot;contracts&quot;, with no code.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 4 times before. New here: drafting bank quant-model documentation, which they call a $10–50M/year problem for big banks.</div><div class="sh">Declare the what, not the how</div><ul><li><strong>Contracts instead of prompts:</strong> Dan traces prompting → context engineering → harnesses and says the next layer up is naming the outcome. If you tell the agent how, you &quot;leave cost and intelligence on the table&quot;. So you declare the goal and end state as a composable &quot;contract&quot; (composition over inheritance) (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=141s" target="_blank" rel="noopener">2:21</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=337s" target="_blank" rel="noopener">5:37</a>)</li><li><strong>It&#39;s just markdown, and event-driven:</strong> OpenProse is all text and built for event-driven multi-agent workflows, not chat. It&#39;s open source (`npx skills add openprose/prose`) with a hosted run.prose.md. Banks like it because it needs no procurement or IT rollout: it runs on whatever coding agent, inference and guardrails they already have (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=366s" target="_blank" rel="noopener">6:06</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=476s" target="_blank" rel="noopener">7:56</a>)</li><li><strong>The compiler is a prompt:</strong> A contract declares sub-agents, their skills and tools (e.g. &quot;always use Exa; if it&#39;s missing, don&#39;t run&quot;), plus inputs and outputs. The runtime is a giant prompt that says &quot;You are the compiler. This is not an analogy.&quot; The kernel is about 70–80K tokens with its own type system on top of markdown. It deliberately leaves sub-agent handling to each harness (&quot;bring your own harness&quot;) (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=598s" target="_blank" rel="noopener">9:58</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=684s" target="_blank" rel="noopener">11:24</a>), (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1073s" target="_blank" rel="noopener">17:53</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1136s" target="_blank" rel="noopener">18:56</a>)</li><li><strong>Pin the how later:</strong> Start loose with a strong model, then &quot;shrink-wrap&quot; a golden run&#39;s trace into a more procedural, reusable workflow to cut cost (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=916s" target="_blank" rel="noopener">15:16</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1002s" target="_blank" rel="noopener">16:42</a>)</li></ul><div class="sh">Event-driven jobs demo (run.prose.md)</div><ul><li><strong>Job = contract + trigger:</strong> Triggers today are cron and webhooks (Slack and GitHub are &quot;just webhooks&quot;). Examples: every GitHub issue goes to a Prose program whose output is a commit, and every PR gets an adversarial review (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=742s" target="_blank" rel="noopener">12:22</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=888s" target="_blank" rel="noopener">14:48</a>)</li><li><strong>&quot;Grumpy senior&quot; PR reviewer:</strong> Raymond asks the voice agent for a Prose program that reviews each new PR &quot;as a grumpy senior developer who doesn&#39;t like AI-generated code&quot;. Anything that spends money needs a manual confirm (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1245s" target="_blank" rel="noopener">20:45</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1308s" target="_blank" rel="noopener">21:48</a>)</li><li><strong>Dogfooding as backpressure:</strong> He built the GitHub-webhooks feature with the system itself. Dozens of PRs went through in a few days, some needing 14 review rounds before the reviewer agents let them pass. Each fresh session is benchmarked against the contract, which avoids models grading their own work (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1384s" target="_blank" rel="noopener">23:04</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1516s" target="_blank" rel="noopener">25:16</a>)</li></ul><div class="sh">DSPy, bank docs and composition</div><ul><li><strong>Opposite of DSPy:</strong> It has the same goal as DSPy (an abstraction over complex workflows) but the opposite design. DSPy boxes every LLM call inside typed, deterministic code, while OpenProse lets the model be the compiler. The weaknesses are that results vary by model (Haiku vs &quot;Fable&quot;) and the agent decides for itself when it&#39;s done. Their planned fix is cheap decision models like Jev as end-of-job verifiers and event routers (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1599s" target="_blank" rel="noopener">26:39</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1689s" target="_blank" rel="noopener">28:09</a>)</li><li><strong>Bank model documentation:</strong> In Codex they type &quot;boot the kernel&quot; then &quot;prose run&quot; on a program that encodes regulators&#39; requirements, and it drafts documentation for the public SOFR curve model. A big bank has about 4,000 models that are re-documented yearly, which they call a $10–50M/year problem. Output is checked against historical docs and rated by quants. The pitch is to run it on-prem with open models so your SOPs stay in-house (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1895s" target="_blank" rel="noopener">31:35</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1952s" target="_blank" rel="noopener">32:32</a>), (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=1993s" target="_blank" rel="noopener">33:13</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=2293s" target="_blank" rel="noopener">38:13</a>)</li><li><strong>Composing contracts:</strong> You can inject several contracts into one run, chain them as a DAG of intermediate &quot;checkpoint&quot; contracts, and propagate upstream changes React-memo-style, with Jev planned as a cheap &quot;semantic memoizer&quot; (not built yet). Their example is researcher, writer and copy-editor sub-agents in about 100 lines of markdown. Use it for repeatable, auditable work; for one-offs, chat is better (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=2482s" target="_blank" rel="noopener">41:22</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=2513s" target="_blank" rel="noopener">41:53</a>), (<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=2517s" target="_blank" rel="noopener">41:57</a>–<a href="https://www.youtube.com/watch?v=7T-gldvgfpo&amp;t=2810s" target="_blank" rel="noopener">46:50</a>)</li></ul></div></article><article class="it full" id="v-W4pnzOURwHQ" data-title="Insurance Claims Are AI&#39;s Messiest Data Problem — Denys Linkov, Wisedocs" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=W4pnzOURwHQ" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+P+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=W4pnzOURwHQ" target="_blank" rel="noopener">Insurance Claims Are AI&#39;s Messiest Data Problem — Denys Linkov, Wisedocs</a></h3><div class="meta">AI Engineer · Denys Linkov, Wisedocs · uploaded 18 Oct, 2:30 PM IST · 44:31</div><div class="verdict v-skim"><b>Verdict:</b> skim from 15:50 — the first 15 minutes are insurance background; the data-quality failures, MLCR results (23:52–27:16) and processing stack (34:24) are the new material.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 4 times before. New here: the first insurance/medical-claims talk (the earlier four were banking, AML and asset management), with a public medical-records benchmark.</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 9 times before. New here: the claim that a human decision-maker plus an auditable pipeline removes &quot;like 70%&quot; of insurers&#39; regulatory concerns.</div><div class="sh">Why claims data is a mess</div><ul><li><strong>Still not digitized:</strong> The fax market is still over $7 billion globally, and EHR adoption was only 8% in 2008. Each US state has its own workers&#39;-comp intake form, so even intake isn&#39;t standardized (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=228s" target="_blank" rel="noopener">3:48</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=303s" target="_blank" rel="noopener">5:03</a>)</li><li><strong>Litigation skews incentives:</strong> Plaintiff lawyers adopted AI faster than insurers because their fees depend on speed and claim size (9–15% in California workers&#39; comp, up to 1/3 or 40% elsewhere). Slow, undigitized insurers are easy targets for repeat and fraudulent claims (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=866s" target="_blank" rel="noopener">14:26</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=889s" target="_blank" rel="noopener">14:49</a>)</li><li><strong>Duplicates and mixed-up records:</strong> Duplicates can be 50% or more of records in some jurisdictions, partly because people re-send to chase slow claims. Records of &quot;Bob Joe&quot; and &quot;Bob Joe Jr.&quot; get mixed together (a HIPAA violation that can sway decisions), and staff copy-paste notes between patients (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=974s" target="_blank" rel="noopener">16:14</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1073s" target="_blank" rel="noopener">17:53</a>)</li><li><strong>8 GB PDFs and missing pieces:</strong> One claim PDF was 8 GB of images, x-rays and ultrasounds, far beyond any context window. Progress notes cite x-rays that aren&#39;t in the package, and an adjuster juggling 200 claims won&#39;t notice (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1222s" target="_blank" rel="noopener">20:22</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1342s" target="_blank" rel="noopener">22:22</a>)</li></ul><div class="sh">MLCR benchmark (with Artificial Analysis)</div><ul><li><strong>Six tiers of medical-records questions:</strong> The questions go from &quot;when did the injury happen&quot; to harder ones where models hallucinate facts that aren&#39;t in the record. Tiers 1–3 are open source, the rest are a private set at Artificial Analysis, and answers are scored on conciseness, accuracy and completeness against expert answers (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1432s" target="_blank" rel="noopener">23:52</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1518s" target="_blank" rel="noopener">25:18</a>)</li><li><strong>Results:</strong> Top accuracy rose from 20% at launch to about 75% a few months later. GPT models were the most accurate but left out key facts, while Anthropic models were more complete; completeness is &quot;still not solved,&quot; and grading uses three judges calibrated against humans (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1551s" target="_blank" rel="noopener">25:51</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1636s" target="_blank" rel="noopener">27:16</a>)</li></ul><div class="sh">From one claim to the portfolio</div><ul><li><strong>Cross-claim analytics:</strong> Once extraction works (e.g. for an insurer paying ~20,000 claims a year), you can track how far patients travel for treatment, map which lawyers, doctors and chiropractors work together, and see which ICD diagnoses co-occur (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1710s" target="_blank" rel="noopener">28:30</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1789s" target="_blank" rel="noopener">29:49</a>)</li><li><strong>Cost analysis:</strong> You can compare physiotherapy prices by doctor, spot a 10% yearly price rise and model &quot;what if we change our network.&quot; He cites a recent $1B overbilling story as what happens when insurers can&#39;t process their data (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1827s" target="_blank" rel="noopener">30:27</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=1913s" target="_blank" rel="noopener">31:53</a>)</li></ul><div class="sh">Stack and Q&amp;A</div><ul><li><strong>Processing stack:</strong> OCR and images first, then entity-extraction models and VLMs, then classifiers and a summary layer that humans verify. Each layer is checked, so the high-value questions run on clean data (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=2064s" target="_blank" rel="noopener">34:24</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=2125s" target="_blank" rel="noopener">35:25</a>)</li><li><strong>Regulation and cost:</strong> A human always makes the decision (e.g. &quot;the diagnoses on page 2 and page 20 differ, take a look&quot;), and that answers about 70% of regulatory concerns. Wisedocs trains its own classifiers to keep costs down (&quot;LLMs are not the right solution for everything&quot;) and admits it can&#39;t yet claim an industry-wide cut in claim time (<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=2330s" target="_blank" rel="noopener">38:50</a>–<a href="https://www.youtube.com/watch?v=W4pnzOURwHQ&amp;t=2564s" target="_blank" rel="noopener">42:44</a>)</li></ul></div></article><article class="it full" id="v-obfPzbapMIM" data-title="Evals for High-Stakes AI Agents — Doneyli De Jesus &amp; Annabell Schäfer, Langfuse" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=obfPzbapMIM" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=obfPzbapMIM" target="_blank" rel="noopener">Evals for High-Stakes AI Agents — Doneyli De Jesus &amp; Annabell Schäfer, Langfuse</a></h3><div class="meta">AI Engineer · Doneyli De Jesus &amp; Annabell Schäfer, Langfuse · uploaded 18 Oct, 1:30 PM IST · 53:32</div><div class="verdict v-skim"><b>Verdict:</b> skim from 25:18 — the expert-comments-to-failure-modes flow, the CI gate on prompt promotion and the business dashboard (to ~45:00) are new; the loop, tracing and judge-vs-code parts repeat Annabell&#39;s earlier Langfuse workshop and yesterday&#39;s Phoenix session.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 30 times before. New here: free-text expert comments turned into failure-mode scores by an LLM, and a Langfuse prompt promotion that triggers a GitHub CI eval gate with a minimum per score. The loop, datasets, LLM-judge vs code evaluators and judge calibration were already in Annabell&#39;s earlier Langfuse workshop (BOCjybvJYM4) and yesterday&#39;s Arize Phoenix workshop (SHMCGrNJJGc).</div><div class="repeat">🔁 Repeat: &#39;agent observability&#39; — seen 18 times before. New here: masking PII before traces are stored, and tracing a voice call (speech-to-text plus a link to the audio).</div><div class="repeat">🔁 Repeat: &#39;human-in-the-loop review&#39; — seen 9 times before. New here: annotation queues on a 10–20% trace sample, where an expert gives a quick score plus a comment.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 4 times before. New here: three ways regulated teams build ground truth (expert curation, shadow runs, full human review then automating parts).</div><div class="sh">Why evals are hard</div><ul><li><strong>The lying refund agent:</strong> A support agent tells the user &quot;I issued your refund&quot; with all metrics green, but the refund tool was never called, and you only learn weeks later (repeat) (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=139s" target="_blank" rel="noopener">2:19</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=165s" target="_blank" rel="noopener">2:45</a>)</li><li><strong>Ground truth in regulated industries:</strong> Build it with domain experts, run the agent in shadow next to the manual process and compare, or run fully human review and gradually automate the parts you trust (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=663s" target="_blank" rel="noopener">11:03</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=690s" target="_blank" rel="noopener">11:30</a>)</li></ul><div class="sh">Banking assistant demo</div><ul><li><strong>Personas, PII and guardrails:</strong> You can test the bot as different customer types (everyday vs ultra-high-net-worth) to check persona guardrails. A credit card number typed in plain text is masked before the trace is stored, and &quot;can I put my savings in Bitcoin&quot; is refused and scored as investment advice (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=831s" target="_blank" rel="noopener">13:51</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1145s" target="_blank" rel="noopener">19:05</a>)</li><li><strong>Datasets:</strong> Keep separate datasets per concern (e.g. red-teaming for prompt injection, unresolved disputes), loaded by CSV upload or by adding good production traces (repeat) (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1343s" target="_blank" rel="noopener">22:23</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1476s" target="_blank" rel="noopener">24:36</a>)</li></ul><div class="sh">Turning expert feedback into evals</div><ul><li><strong>Annotation queue:</strong> Sample 10–20% of traces (e.g. only disputes) and let the risk expert give a yes/no or 1–10 score plus a comment like &quot;citation is not there,&quot; about 30 seconds each, even dictated with Wispr Flow (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1570s" target="_blank" rel="noopener">26:10</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1682s" target="_blank" rel="noopener">28:02</a>)</li><li><strong>LLM finds the failure modes:</strong> Ask experts for raw comments, not categories, then have an LLM cluster them into failure modes. These become the scores, e.g. cites the expected source, formal register, no unsolicited upsell (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1704s" target="_blank" rel="noopener">28:24</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1793s" target="_blank" rel="noopener">29:53</a>)</li><li><strong>Mix judge types:</strong> Combine LLM-as-judge with deterministic code checks (a regex exact match gives the same output every time) because judges have a &quot;nonzero chance&quot; of being wrong (repeat) (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1859s" target="_blank" rel="noopener">30:59</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=1949s" target="_blank" rel="noopener">32:29</a>)</li></ul><div class="sh">Gates and dashboards</div><ul><li><strong>Prompt change → CI gate:</strong> A Langfuse automation fires on prompt changes and starts a GitHub CI job. Promoting prompt v4 to production ran the dataset experiment and passed or failed it against a minimum score for each evaluator, and the flow could go on to open the PR (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=2112s" target="_blank" rel="noopener">35:12</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=2316s" target="_blank" rel="noopener">38:36</a>)</li><li><strong>Dashboard for stakeholders:</strong> 1,400 interactions in 7 days needed no human and cost under $7, versus paying a contact-center worker $15–20 an hour. The top failure modes were out of scope, informal register and unresolved disputes, with 18% thumbs-down and 89 investment-advice flags (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=2433s" target="_blank" rel="noopener">40:33</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=2652s" target="_blank" rel="noopener">44:12</a>)</li><li><strong>Coding agents and Q&amp;A:</strong> &quot;Fix my agent, make no mistakes&quot; gives slop, so automate instrumenting and eval runs but keep human taste on the datasets, starting with the Langfuse agent skill. In Q&amp;A: Langfuse moved from Postgres to ClickHouse for scale, and you should calibrate a judge against human labels: begin with too many false positives, then tune down (<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=2765s" target="_blank" rel="noopener">46:05</a>–<a href="https://www.youtube.com/watch?v=obfPzbapMIM&amp;t=3203s" target="_blank" rel="noopener">53:23</a>)</li></ul></div></article><article class="it full" id="v-q4WC4TowkBo" data-title="Teach Your Agent to Prove It&#39;s Done — Nick Nisi &amp; Zack Proser, WorkOS" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=q4WC4TowkBo" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=q4WC4TowkBo" target="_blank" rel="noopener">Teach Your Agent to Prove It&#39;s Done — Nick Nisi &amp; Zack Proser, WorkOS</a></h3><div class="meta">AI Engineer · Nick Nisi &amp; Zack Proser, WorkOS · uploaded 18 Oct, 12:30 PM IST · 1:01:04</div><div class="verdict v-skim"><b>Verdict:</b> skim from 17:31 — the snack CLI walkthrough, the &quot;not done&quot; moment and the judge/eval segment (to ~46:00) are the substance; the opening and Q&amp;A restate well-covered verification ideas.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 18 times before. New here: a per-app verifier CLI (&quot;snack&quot;) with doctor/drive/look/prove/judge commands that agents run themselves.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 30 times before. New here: a saboteur/detective bug-planting game as an eval baseline, plus saving every run&#39;s &quot;receipts&quot; as future hill-climbing data.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 43 times before. New here: WorkOS&#39;s in-house CTX verifier service and Riker PR-babysitter.</div><div class="sh">Why &quot;done&quot; isn&#39;t done</div><ul><li><strong>The waitlist that lies:</strong> In the Midnight Snack Club demo app the form says &quot;success&quot; and shows the email, but a page reload shows nobody signed up — the UI updated and nothing was persisted, so a UI-only check would pass (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=325s" target="_blank" rel="noopener">5:25</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=379s" target="_blank" rel="noopener">6:19</a>)</li><li><strong>Receipts, not model prose:</strong> Decompose tasks and tell each agent exactly how to verify &quot;done&quot;; one WorkOS engineer ships ~900 PRs a month with no incidents this way. Demand screenshots, videos, test results and smoke tests instead of &quot;it passes, looks good&quot; (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=640s" target="_blank" rel="noopener">10:40</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=735s" target="_blank" rel="noopener">12:15</a>)</li><li><strong>CTX and Riker:</strong> Zack&#39;s CTX (a Cloudflare web app that began as cross-harness memory and a secrets broker) now hosts verifiers — agents ask over MCP &quot;am I done?&quot;, and a PR verifier checks the GitHub API that the PR exists and merge checks pass before marking the step satisfied. Nick&#39;s Riker babysits PRs (fixing tests and review comments) and pings him only when needed (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=757s" target="_blank" rel="noopener">12:37</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=992s" target="_blank" rel="noopener">16:32</a>)</li></ul><div class="sh">Give the agent eyes</div><ul><li><strong>A script beats a prompt:</strong> Instructions like &quot;always verify the change in a browser&quot; leave room to interpret; a deterministic script the agent reruns until clean is uniform across 30 agents, and Lauren Tan and others say a bespoke verifier CLI is what unlocked their velocity (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1104s" target="_blank" rel="noopener">18:24</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1218s" target="_blank" rel="noopener">20:18</a>)</li><li><strong>The snack CLI:</strong> A template per-app tool: up/down/doctor (is the DB running, network ok), drive (join, reload, reset), look (JSON snapshot, network, console, local storage, screenshot), then prove (deterministic Playwright check that the email really landed) and judge (a fast &quot;system one&quot; model) (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1221s" target="_blank" rel="noopener">20:21</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1298s" target="_blank" rel="noopener">21:38</a>)</li><li><strong>Make it feedback-loopable:</strong> Amp&#39;s bouncing-ball example — the model can&#39;t see a canvas, but printing the ball&#39;s coordinates each frame exposes a jump of more than a pixel. Also: a successful screenshot isn&#39;t proof, and explicit error messages let agents self-heal (repeat) (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1710s" target="_blank" rel="noopener">28:30</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1756s" target="_blank" rel="noopener">29:16</a>, <a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1876s" target="_blank" rel="noopener">31:16</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=1996s" target="_blank" rel="noopener">33:16</a>)</li><li><strong>The &quot;I&#39;m not done&quot; moment:</strong> `snack doctor` passes, `snack join ada@example.test` reports success, but `snack storage` is empty — the point where the agent realizes it isn&#39;t done instead of dropping the work on you (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2157s" target="_blank" rel="noopener">35:57</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2217s" target="_blank" rel="noopener">36:57</a>)</li></ul><div class="sh">Judges, evals and receipts</div><ul><li><strong>Judge instead of string matching:</strong> After the persistence fix the page says &quot;You&#39;re in, your seat is confirmed&quot; rather than &quot;waitlisted&quot;, so the judge fails the contract; a fast system-one model judges intent without tight coupling to on-screen text (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2352s" target="_blank" rel="noopener">39:12</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2422s" target="_blank" rel="noopener">40:22</a>)</li><li><strong>Start an eval baseline:</strong> `pnpm snack up --bug random` plants a hidden bug and the detective must name it with evidence (outcomes: right bug, overclaimed, blamed a bug that wasn&#39;t there). The point: create a baseline, run it consistently, and have every PR exercise it (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2507s" target="_blank" rel="noopener">41:47</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2552s" target="_blank" rel="noopener">42:32</a>, <a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2744s" target="_blank" rel="noopener">45:44</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=2770s" target="_blank" rel="noopener">46:10</a>)</li><li><strong>Keep every run&#39;s receipts:</strong> Saved runs become data for future self-improving (RSI) loops — e.g. a nightly agent spots eight caching-module failures and opens a PR with proof; attach walkthrough recordings so morning PR review starts with &quot;did it reach the goal&quot; (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3057s" target="_blank" rel="noopener">50:57</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3135s" target="_blank" rel="noopener">52:15</a>)</li></ul><div class="sh">Q&amp;A</div><ul><li><strong>How to enforce it:</strong> Easiest is an agents.md (not CLAUDE.md) saying &quot;run the verifier before opening a PR&quot;; shared hooks and CI work too. Greptile 5/5 plus green CI already gives Nick confidence — this just gets there in fewer turns. Emerging pattern: an agent that watches Datadog and feature flags during rollout and reverts (<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3308s" target="_blank" rel="noopener">55:08</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3320s" target="_blank" rel="noopener">55:20</a>, <a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3501s" target="_blank" rel="noopener">58:21</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3528s" target="_blank" rel="noopener">58:48</a>, <a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3608s" target="_blank" rel="noopener">1:00:08</a>–<a href="https://www.youtube.com/watch?v=q4WC4TowkBo&amp;t=3625s" target="_blank" rel="noopener">1:00:25</a>)</li></ul></div></article><article class="it full" id="v-OfNajAPiGsM" data-title="Anthropic Says Self-Replicating AI Is Real... (sort of)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=OfNajAPiGsM" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+M+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=OfNajAPiGsM" target="_blank" rel="noopener">Anthropic Says Self-Replicating AI Is Real... (sort of)</a></h3><div class="meta">Better Stack · Better Stack · uploaded 18 Oct, 11:15 PM IST · 6:05</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — 6 minutes, a new threat model with concrete numbers and a fair &quot;less scary&quot; take.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 19 times before. New here: Anthropic&#39;s Frontier Red Team test of an AI &quot;worm&quot; that copies itself between devices — a new threat, not prompt injection or sandboxing.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 41 times before. New here: a 26B Gemma 4 split two layers per box across 15 $55 Android TV boxes.</div><div class="sh">The experiment</div><ul><li><strong>Small enough:</strong> Anthropic networked 15 off-brand Android TV boxes (~$55, ~4 GB RAM each) and split Gemma 4 (26B, 4-bit) two layers per box. It works but runs at 0.39 tokens/s, nearly a minute per sentence (<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=38s" target="_blank" rel="noopener">0:38</a>–<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=112s" target="_blank" rel="noopener">1:52</a>)</li><li><strong>Smart enough:</strong> A mini Claude Code-style agent worm on 8 sealed Android cloud machines had to find a peer, get in through an open no-password ADB debug port (made easy on purpose) and get a model running. Separately, Qwen 3.5 9B got a model running on 8 of 9 hardware types, from a Jetson Nano to an RTX 4090 (<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=113s" target="_blank" rel="noopener">1:53</a>–<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=183s" target="_blank" rel="noopener">3:03</a>)</li><li><strong>Only one model did it all:</strong> The worm&#39;s brain stayed on a separate server and every model deployed Llama 3.1 8B as a stand-in. Only GLM 5.2 spread to all 8 machines (in 4 of 5 runs, 7 of 8 in the other); every other model failed every time (<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=185s" target="_blank" rel="noopener">3:05</a>–<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=229s" target="_blank" rel="noopener">3:49</a>)</li></ul><div class="sh">Why it&#39;s less scary (for now)</div><ul><li><strong>The two don&#39;t overlap yet:</strong> GLM 5.2 is ~753B parameters, far too big for a TV box. Anthropic estimates an ~8B model could be that capable by end of 2026, though that&#39;s a rough guess (<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=231s" target="_blank" rel="noopener">3:51</a>–<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=270s" target="_blank" rel="noopener">4:30</a>)</li><li><strong>Hurdles:</strong> Open ADB is realistic — the Kimwolf botnet already holds 2M+ devices, mostly Android TV boxes that ship with ADB on and no password (Krebs on Security). But moving multi-GB weights is noisy for ISPs, a 9B worm needs 28–51 hours per device, and 2M boxes add up to only about 40 H100s (<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=273s" target="_blank" rel="noopener">4:33</a>–<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=334s" target="_blank" rel="noopener">5:34</a>)</li><li><strong>Fear marketing?</strong> Every model tested was open-weight, so critics on Hacker News and Reddit read it as a push toward banning open models (<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=336s" target="_blank" rel="noopener">5:36</a>–<a href="https://www.youtube.com/watch?v=OfNajAPiGsM&amp;t=347s" target="_blank" rel="noopener">5:47</a>)</li></ul></div></article></div>',1))])}const D=u(A,[["render",W]]);export{j as __pageData,D as default};
